import * as E from'./engine.js';
const titles={909:'Estación espacial',907:'Astillero civil',908:'Puerto avanzado'};
export function homelandPanel(s,h){const{fmt}=h;if(!s.homeland)return'';const enemies=E.homeEnemies(s),defenses=E.homeDefenses(s);return'<div class="section-label">ESCENARIO DEL ARCHIPIÉLAGO</div><p>'+(!s.homeland.completed?enemies.length+' patrullas orcas y '+defenses.length+' defensas armadas protegen la prisión del noreste.':'Has asegurado el primer sector enemigo del archipiélago.')+' Las estructuras del escenario están en el mismo mapa que tu base.</p><button class="wide primary" data-action="home-briefing">'+(s.homeland.completed?'Consultar archipiélago asegurado':'Localizar enemigos y preparar el rescate')+'</button><div class="home-landmarks">'+E.homeStructures(s).filter(b=>b.landmark).map(b=>'<button data-action="home-object" data-id="'+b.id+'">'+titles[b.sourceId]+' <small>'+Math.floor(b.x)+', '+Math.floor(b.y)+'</small></button>').join('')+'</div><p class="tiny">'+fmt(E.homeStructures(s).length)+' estructuras y elementos conservados del escenario inicial y su primer capítulo. No se suman a tus edificios productivos.</p>';}
export function homelandBriefing(s,h){const{head,esc}=h,enemies=E.homeEnemies(s),defenses=E.homeDefenses(s),target=enemies[0]||defenses[0]||E.homeStructures(s).find(v=>v.tag==='prison');return head('MISMO ARCHIPIÉLAGO · CAPÍTULO INICIAL','Rescate en territorio orco')+'<p>El escenario recupera los nueve enemigos, muros, torretas, prisión y elementos de la llave del primer capítulo preservado. Quedan '+enemies.length+' patrullas y '+defenses.length+' defensas armadas.</p><p>Desplaza tus tropas por tierra y cruza los puentes para llegar al noreste. El combate empieza al acercarse a una patrulla o al elegir Asegurar. Puedes dar órdenes sobre todo el mapa y retirarte. Las bajas de tu ejército son permanentes; el daño a los enemigos se conserva.</p>'+(target?'<button class="wide" data-action="home-focus" data-id="'+esc(target.id)+'">Centrar primer objetivo</button>':'')+(!s.homeland.completed?'<button class="primary wide" data-action="home-battle" '+(!s.army.length?'disabled':'')+'>Asegurar el archipiélago</button><p class="tiny">Neutraliza las patrullas y las defensas armadas. El premio de 650 oro, 300 madera, 250 petróleo y 180 acero se concede una sola vez. Las reservas sin espacio se conservan.</p>':'<p>Sector asegurado. Las instalaciones neutrales siguen disponibles para inspección.</p>');}
export function homelandObject(s,id,h){const{head,esc,img,fmt}=h,o=E.homeObject(s,id);if(!o)return head('ARCHIPIÉLAGO','Objeto no disponible.');const name=titles[o.sourceId]||E.BUILDINGS[o.type]?.name||E.UNITS[o.type]?.name;return head(o.side==='enemy'?'PRESENCIA ENEMIGA':'ESTRUCTURA DEL ESCENARIO',esc(name))+img(o.type,o.level,!!E.UNITS[o.type],'hero-image')+'<p>Posición '+Math.floor(o.x)+', '+Math.floor(o.y)+' · integridad '+fmt(o.hp)+' / '+fmt(o.maxHp)+'.</p><p>'+(o.landmark?'Instalación neutral situada en sus coordenadas del escenario original. Conserva su tamaño y sus apoyos costeros; no pertenece a la producción ni a la cola de entrenamiento de tu base.':o.tag==='prison'?'Prisión del primer capítulo. Asegura las patrullas y sus defensas para liberar este puesto.':o.side==='enemy'?'Objetivo del archipiélago. Se puede combatir con tu ejército en este mismo mapa.':'Elemento conservado del capítulo original.')+'</p><button class="wide" data-action="home-focus" data-id="'+esc(id)+'">Centrar en el mapa</button>'+(o.side==='enemy'&&!s.homeland.completed?'<button class="primary wide" data-action="home-battle" '+(!s.army.length?'disabled':'')+'>Iniciar operación en el archipiélago</button>':'');}
